```openscad
// T-shaped nut for aluminium extrusion slot
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z)
// Positioned per the user's coordinates: x -10..10, y -5..5, z 0..7

// ---------------- Parameters ----------------
flange_w     = 10;    // flange width (Y)
flange_t     = 3;     // flange thickness (Z)
neck_w       = 7;     // neck width (Y)
neck_h       = 4;     // neck height above flange top (Z)
screw_d      = 3.4;   // central screw hole diameter
length_x     = 20;    // part length along X axis
eps          = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange: z = 0 to 3
        translate([-length_x/2, -flange_w/2, 0])
            cube([length_x, flange_w, flange_t]);

        // Centred neck: z = 3 to 7
        translate([-neck_w/2, -neck_w/2, flange_t])
            cube([neck_w, neck_w, neck_h]);
    }

    // Vertical screw hole through the full height
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_t + neck_h + 2*eps);
}
