```openscad
// Anti-vibration foot for benchtop instrument
// Print orientation: flat on bed, recess facing down

// ---------- Parameters ----------
foot_d_bottom   = 50;    // frustum diameter at z = 0 (mm)
foot_d_top      = 42;    // frustum diameter at top (mm)
foot_h          = 12;    // frustum height (mm)

recess_d        = 44;    // rubber pad recess diameter (mm)
recess_depth    = 3;     // rubber pad recess depth (mm)

screw_d         = 4.5;   // central screw hole diameter (mm)

eps             = 0.5;   // cutter overshoot past faces (mm)
$fn             = 128;   // curve resolution

// ---------- Model ----------
difference() {
    // Truncated cone, centred on Z axis
    cylinder(d1 = foot_d_bottom, d2 = foot_d_top, h = foot_h);

    // Round recess in bottom face for rubber pad
    translate([0, 0, -recess_depth])
        cylinder(d = recess_d, h = recess_depth + eps);

    // Through hole for screw along axis
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = foot_h + 2 * eps);
}
```

