    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles: cylinders whose axes run along X at y = 15, z = 3.5
    for (i = [0 : knuckle_n - 1]) {
        translate([x0 + i * pitch, 15, 0])
            difference() {
                // Cylinder extended above the plate (eps in Z)
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = plate_thk + 2 * eps, center = true);
                // Pin hole through the knuckle
                translate([0, 0, -eps])
                    cylinder(d = pin_d, h = plate_thk + 2 * eps);
            }
    }
}
