// Flat 8-pointed star plate with a central through-hole

n_points   = 8;    // number of star points
r_outer    = 30;   // radius of outer (tip) points, mm
r_inner    = 18;   // radius of inner (valley) points, mm
thickness  = 3;    // plate thickness, mm
hole_d     = 6;    // centre hole diameter, mm
cut_extra  = 0.5;  // extra length on cutting shapes past faces, mm
$fn        = 96;   // facet count for curved shapes

// Star outline: alternate outer and inner points, first outer point on +X
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (
            a = i * 180 / n_points,
            r = (i % 2 == 0) ? r_outer : r_inner
        )
        [r * cos(a), r * sin(a)]
];

difference() {
    // Star plate resting on the bed
    linear_extrude(height = thickness)
        polygon(points = star_pts);

    // Central through-hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = thickness + 2 * cut_extra, $fn = 96);
}
```

