// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 to plate_t

// ---- Parameters ----
outer_r   = 30;   // distance of outer points from centre
inner_r   = 15;   // distance of inner points from centre
points    = 8;    // number of outer/inner point pairs
plate_t   = 5;    // plate thickness
hole_d    = 6;    // central through-hole diameter
eps       = 0.5;  // cutter overshoot past faces

$fn = 96;

// ---- Model ----
difference() {
    // Star outline (2D, then extruded)
    hull() {
        for (i = [0 : points - 1]) {
            rotate([0, 0, i * 360 / points])
                translate([0, 0, 0])
                    if (i % 2 == 0)
                        cylinder(h = plate_t, r = outer_r);
                    else
                        cylinder(h = plate_t, r = inner_r);
        }
    }

    // Central hole, extends past top and bottom faces
    translate([0, 0, -eps])
        cylinder(h = plate_t + 2 * eps, d = hole_d);
}
