```openscad
// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 to plate_t

// ---------- Parameters ----------
outer_r   = 30;   // distance of outer points from centre
inner_r   = 15;   // distance of inner points from centre
point_n   = 8;    // number of points (and inner points)
plate_t   = 5;    // plate thickness
hole_d    = 6;    // central through-hole diameter
eps       = 0.5;  // cutter overshoot past faces

$fn = 96;

// ---------- Model ----------
difference() {
    // Star outline: outer points at 0,45,... deg, inner points shifted by 22.5 deg
    hull() {
        for (i = [0 : point_n - 1]) {
            rotate([0, 0, i * 360 / point_n])
                translate([0, 0, 0])
                    union() {
                        // outer point
                        translate([outer_r, 0, 0])
                            cube([outer_r, 2 * outer_r, plate_t]);
                        // inner point
                        translate([inner_r, 0, 0])
                            cube([inner_r, 2 * inner_r, plate_t]);
                    }
        }
    }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
