```openscad
// Tapered riser block for a beaker, with a square pocket in the top face
// Print orientation: flat on bed, bottom face at z = 0

// ---------- Dimensions (mm) ----------
base_size      = 80;   // bottom square side (z = 0)
top_size       = 50;   // top square side (z = 30)
height         = 30;   // overall height
pocket_size    = 40;   // square pocket side
pocket_depth   = 5;    // square pocket depth from top face
eps            = 0.5;  // overshoot for clean boolean cuts

$fn = 64;

// ---------- Model ----------
difference() {
    // Square frustum: bottom square -> top square with sloping sides
    hull() {
        translate([-base_size/2, -base_size/2, 0])
            cube([base_size, base_size, 0]);
        translate([-top_size/2, -top_size/2, height])
            cube([top_size, top_size, 0]);
    }

    // Square pocket, centred, open at the top face
    translate([0, 0, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
```

