// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 110;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 10;    // length of each grip-gauge transition (X)

// ---- Derived ----
grip_x0 = -(total_length / 2) + grip_length;   // grip start X
gauge_x0 = grip_x0 + grip_length;              // gauge start X
trans_x0 = gauge_x0 - transition_len;          // transition start X

// ---- Model ----
union() {
    // Right grip
    translate([grip_x0, -grip_width / 2, 0])
        cube([grip_length, grip_width, thickness]);

    // Gauge section
    translate([gauge_x0, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);

    // Left grip
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([grip_length, grip_width, thickness]);

    // Right transition (grip -> gauge)
    translate([trans_x0, 0, 0])
        linear_extrude(thickness)
            polygon(points = [
                [trans_x0, grip_width / 2],
                [gauge_x0 - transition_len / 2, gauge_width / 2],
                [gauge_x0 - transition_len / 2, -gauge_width / 2],
                [trans_x0, -grip_width / 2]
            ]);

    // Left transition (gauge -> grip)
    translate([-total_length / 2 + transition_len, 0, 0])
        linear_extrude(thickness)
            polygon(points = [
                [trans_x0 + transition_len, grip_width / 2],
                [gauge_x0 - transition_len / 2, gauge_width / 2],
                [gauge_x0 - transition_len / 2, -gauge_width / 2],
                [trans_x0 + transition_len, -grip_width / 2]
            ]);
}
