half_gauge = gauge_length / 2;
half_grip  = grip_length / 2;
// width at the start of each transition (grip end)
transition_w0 = grip_width - (gauge_width - grip_width) * transition_len / (grip_width + gauge_width);

difference() {
    // Main body
    union() {
        // Central gauge section
        translate([-half_gauge, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Grip sections
        for (s = [-1, 1])
            translate([s * (half_gauge + transition_len) - half_grip, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
    }

    // Rounded notches at each grip-gauge transition
    for (s = [-1, 1])
        translate([s * (half_gauge + transition_len), 0, -1])
            rotate([0, 90, 0])
                linear_extrude(thickness)
                    circle(d = transition_w0, h = transition_len + 2);
