    for (s = [-1, 1])
        translate([s * half_gauge, 0, 0])
            linear_extrude(height = thickness)
                polygon(points = [
                    [0, 0],
                    [transition_len, 0],
                    [transition_len, s * (transition_w0 + (transition_w1 - transition_w0) * 0.5)],
                    [0, s * (transition_w0 + (transition_w1 - transition_w0) * 0.5)]
