// Flat tensile test specimen (dog bone)
// Lies flat on the bed (z = 0), centred on the origin in X and Y.

// ---------------- Parameters ----------------
thickness      = 4;    // specimen thickness (Z)
total_length   = 120;  // overall length (X)
gauge_width    = 8;    // width of narrow gauge section (Y)
gauge_length   = 30;   // length of gauge section (X)
grip_width     = 15;   // width of grip sections (Y)
grip_length    = 30;   // length of each grip section (X)
trans_length   = 15;   // length of each linear transition (X)

// Derived X positions (from centre outward)
x_gauge = gauge_length / 2;              // end of gauge section  (15)
x_trans = x_gauge + trans_length;        // end of transition     (30)
x_end   = x_trans + grip_length;         // end of grip / part    (60)

gw = gauge_width / 2;                    // half gauge width
pw = grip_width / 2;                     // half grip width

// Sanity check: computed length should equal total_length
assert(abs(2 * x_end - total_length) < 1e-6,
       "Section lengths do not add up to total_length");

