            translate([(half_gauge + trans_len) / 2, -grip_w / 2, 0])
                linear_extrude(thickness)
                    polygon(points = [
                        [0, grip_w / 2],
                        [-trans_len, grip_w / 2],
                        [-trans_len, gauge_w / 2],
                        [0, gauge_w / 2]
