// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to specimen_t

$fn = 64;

// --- Dimensions (mm) ---
specimen_t   = 3;     // thickness (Z)
gauge_w      = 6;     // gauge section width (Y)
gauge_l      = 40;    // gauge section length (X)
grip_w       = 20;    // grip section width (Y)
grip_l       = 25;    // grip section length (X)
transition_l = 15;    // transition section length (X)
eps          = 0.5;   // cutter overshoot past faces

// Derived
total_l = 2 * grip_l + gauge_l + 2 * transition_l;   // 120 mm

// Width at a given X position (profile in XY, extruded in Z)
function width(x) =
    if (x < -grip_l)       grip_w + (grip_w - gauge_w) * (x + grip_l) / transition_l
    else if (x <= -gauge_l) grip_w
    else if (x < gauge_l)  gauge_w
    else if (x <= gauge_l + transition_l) grip_w + (grip_w - gauge_w) * (gauge_l + transition_l - x) / transition_l
    else                   grip_w;

difference() {
    // Main specimen
    translate([-total_l / 2, -specimen_t / 2, 0])
        linear_extrude(height = specimen_t)
            polygon([for (sx = [-1, 1]) for (y = [0 : 0.01 : specimen_t])
                [sx * (total_l / 2 - grip_l - transition_l - gauge_l / 2) +
                 (sx > 0 ? grip_l + transition_l : -grip_l - transition_l) +
                 (sx > 0 ? transition_l : 0) * (y / specimen_t - 0.5) * (grip_w - gauge_w),
                 y - specimen_t / 2]));

    // Central grip block (overlaps gauge and one transition on each side)
    translate([-grip_l - transition_l - gauge_l / 2, -specimen_t / 2, -eps])
        cube([gauge_l + transition_l + eps, specimen_t + 2 * eps, 2 * eps]);
}
