// Stiffened cover panel: flat plate with 4 transverse ribs
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 120;   // plate length along X (mm)
plate_wid   = 60;    // plate width along Y (mm)
plate_thk   = 2;     // plate thickness (mm), z = 0..2

rib_thk     = 3;     // rib thickness along X (mm)
rib_h       = 6;     // rib height above plate (mm), z = 2..8
rib_count   = 4;     // number of ribs
rib_pitch   = 24;    // centre-to-centre spacing of ribs (mm)
rib_offset  = 24;    // distance of outer rib centres from plate ends (mm)

eps         = 0.5;   // overlap for clean booleans (mm)
$fn         = 64;    // curve resolution (no curves here, set per rules)

// ---------------- Derived ----------------
plate_h = plate_thk + rib_h;   // overall height (mm)

// Check: 5 equal parts -> pitch = plate_len / 5 = 24 mm
assert(abs(rib_pitch - plate_len / 5) < 0.001, "Rib pitch must give 5 equal parts");
assert(abs(rib_offset - rib_pitch / 2) < 0.001, "Outer rib must be 24 mm from each end");

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on origin along X
    for (i = [0 : rib_count - 1]) {
        x_c = (i - (rib_count - 1) / 2) * rib_pitch;
        translate([x_c - rib_thk / 2, -plate_wid / 2, plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
