// Powder measuring scoop
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
outer_radius   = 12;    // outer radius of spherical bowl (mm)
wall_thickness = 2;     // wall thickness of bowl (mm)
handle_width  = 10;    // handle width along Y (mm)
handle_thick  = 4;     // handle thickness along Z (mm)
handle_x0     = 10;    // handle start position along X (mm)
handle_x1     = 112;   // handle end position along X (mm)
cut_extra     = 0.5;   // extra length for cutting shapes past faces (mm)

$fn = 96;              // curve resolution

// Derived values
rim_z      = outer_radius;               // rim height (lower half: z = 0..12)
bottom_z   = outer_radius - wall_thickness; // bottom of outer sphere (z = 10)
inner_r    = outer_radius - wall_thickness;  // inner radius of hollow
handle_y0  = -handle_width / 2;          // handle Y start
handle_y1  =  handle_width / 2;          // handle Y end

// ---------------- Model ----------------
union() {
    // Hollow spherical bowl (lower half only)
    difference() {
        cylinder(h = bottom_z + cut_extra, r = outer_radius);
        translate([0, 0, bottom_z])
            cylinder(h = wall_thickness + cut_extra, r = inner_r);
    }

    // Flat handle, top face flush with rim (z = 12)
    translate([handle_x0, handle_y0, rim_z - handle_thick])
        cube([handle_x1 - handle_x0, handle_width, handle_thick]);
}
