handle_y0 = -handle_w / 2;        // -4 to +4 in Y

// ---------------- Model ----------------
union() {
    // Lower half of hollow sphere: z = 0 to z = 15
    difference() {
        translate([0, 0, sphere_r])
            sphere(r = sphere_r);
        translate([0, 0, sphere_r - wall])
            sphere(r = sphere_r - wall);
    }

    // Flat handle along +X, centred on y = 0
    translate([handle_x0, handle_y0, rim_z - handle_t])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}
