            rotate([0, 0, i * 360 / points])
                translate([0, 0, 0])
                    union() {
                        // outer point
                        cylinder(r = outer_r, h = thickness);
                        // inner point (overlaps the core, ensures hull reaches it)
                        translate([0, 0, -eps])
                            cylinder(r = inner_r, h = thickness + 2 * eps);
                    }
        }
    }
    // central hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
