// Flat tensile test specimen (dog bone)
// Lies flat on the bed, symmetric about the origin, length along X.

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;    // specimen thickness (Z)
total_length   = 110;  // overall length (X)
gauge_width    = 8;    // gauge section width (Y)
gauge_length   = 40;   // gauge section length (X)
grip_width     = 19;   // grip section width (Y)
grip_length    = 25;   // grip section length (X), each end
trans_length   = 10;   // linear transition length (X), each side

// ---- Derived positions (half-lengths from origin along X) ----
x_gauge = gauge_length / 2;              // 20  end of gauge
x_trans = x_gauge + trans_length;        // 30  end of transition
x_end   = x_trans + grip_length;         // 55  end of grip (= total_length/2)

hg = gauge_width / 2;  // half gauge width
hw = grip_width / 2;   // half grip width

// Consistency check
assert(abs(2 * x_end - total_length) < 1e-6,
       "Section lengths do not add up to total_length");

// ---- Outline (top view), counter-clockwise ----
outline = [
    [-x_end,   -hw], [-x_trans, -hw], [-x_gauge, -hg],
    [ x_gauge, -hg], [ x_trans, -hw], [ x_end,   -hw],
    [ x_end,    hw], [ x_trans,  hw], [ x_gauge,  hg],
    [-x_gauge,  hg], [-x_trans,  hw], [-x_end,    hw]
];

// ---- Part ----
linear_extrude(height = thickness)
    polygon(outline);
```

```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to specimen_t

$fn = 64;

// --- Dimensions (mm) ---
specimen_t   = 3;     // thickness (Z)
gauge_w      = 8;     // gauge section width (Y)
gauge_l      = 40;    // gauge section length (X)
grip_w       = 19;    // grip section width (Y)
grip_l       = 25;    // grip section length (X)
transition_l = 10;    // transition section length (X)

// Derived
total_l = 2 * grip_l + gauge_l + 2 * transition_l; // 110 mm

difference() {
    // Body
    union() {
        // Grip sections
        for (s = [-1, 1])
            translate([s > 0 ? grip_l - transition_l : -grip_l, -grip_w / 2, 0])
                cube([grip_l + transition_l, grip_w, specimen_t]);
        // Gauge section
        translate([-gauge_l / 2, -gauge_w / 2, 0])
            cube([gauge_l, gauge_w, specimen_t]);
        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1])
            translate([s > 0 ? grip_l - transition_l : -grip_l, 0, 0])
                rotate([90, 0, 0])
                    linear_extrude(specimen_t)
                        polygon([
                            [0, -grip_w / 2],
                            [transition_l, -grip_w / 2],
                            [transition_l, grip_w / 2],
                            [0, grip_w / 2]
                        ]);
    }

    // Optional through-hole in gauge section for alignment
    translate([-gauge_l / 2, 0, -1])
        cylinder(d = 3.4, h = gauge_l + 2);
}
