```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // length of each grip-to-gauge transition (X)

// ---- Derived ----
mid_x = -total_length / 2 + grip_length + transition_len;  // gauge centre X
w1    = grip_width;                                        // start width
w2    = gauge_width;                                       // end width

module dogbone() {
    hull() {
        for (s = [-1, 1]) {
            translate([s * grip_length - grip_length / 2, -w1 / 2, 0])
                cube([grip_length, w1, thickness]);   // grip sections
            translate([mid_x - transition_len, -w1 / 2, 0])
                cube([transition_len, w1, thickness]); // right transition
            translate([mid_x - gauge_length - transition_len, -w2 / 2, 0])
                cube([gauge_length, w2, thickness]);   // gauge section
            translate([mid_x + transition_len, -w1 / 2, 0])
                cube([transition_len, w1, thickness]); // left transition
        }
    }
}

dogbone();
```

