        grip_width/2 + (gauge_width - grip_width)/2 *
            (x - (grip_x0 - transition_len)) / transition_len;
    else if (x <= gauge_x0 + transition_len)
        gauge_width/2 + (grip_width - gauge_width)/2 *
            (x - gauge_x0 - transition_len) / transition_len;
    else
        grip_width/2 + (gauge_width - grip_width)/2 *
            (x - (gauge_x0 + transition_len)) / transition_len;

