// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
rim_od        = 80;   // outer diameter of rim
rim_width     = 4;    // rim width (Z)
hub_d         = 16;   // hub diameter
axle_hole     = 5;    // axle hole diameter
spoke_count   = 4;    // number of spokes
spoke_w       = 4;    // spoke width
spoke_start   = 0;    // angle of first spoke (deg, +X axis)
eps           = 0.5;  // cutter overshoot past faces

$fn = 128;

// ---- Model ----
union() {
    // Outer rim
    cylinder(d = rim_od, h = rim_width, $fn = 128);

    // Hub with axle hole
    translate([0, 0, -eps])
        difference() {
            cylinder(d = hub_d, h = rim_width + 2 * eps, $fn = 64);
            translate([0, 0, -eps])
                cylinder(d = axle_hole, h = rim_width + 3 * eps, $fn = 64);
        }

    // Spokes: radial slots from hub to rim
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start + i * 360 / spoke_count;
        translate([0, 0, -eps])
            rotate([0, 0, a])
                difference() {
                    translate([0, -spoke_w / 2, 0])
                        cube([rim_od / 2, spoke_w, rim_width + 2 * eps]);
                    // remove overlap with hub (clean fusion)
                    translate([hub_d / 2 - 1, -spoke_w / 2, -eps])
                        cube([hub_d - 2, spoke_w, rim_width + 3 * eps]);
                }
    }
}
