// Powder measuring scoop: hemispherical bowl + flat handle
// Print orientation: bowl bottom on bed (z = 0), opening upward

$fn = 96;

// ---- Bowl ----
bowl_outer_r   = 10;     // outer radius of bowl sphere
bowl_wall      = 1.5;    // wall thickness
bowl_inner_r   = bowl_outer_r - bowl_wall; // 8.5 mm inner radius
bowl_center_z  = 10;     // sphere centre height (rim height)

// ---- Handle ----
handle_x_start = 8.5;    // handle start along +X
handle_x_end   = 110;    // handle end along +X
handle_width   = 8;      // Y width
handle_thick   = 3;      // Z thickness
handle_top_z   = bowl_center_z;              // flush with rim
handle_bot_z   = handle_top_z - handle_thick; // z = 7

eps = 0.5;               // overcut for clean differences

module bowl() {
    difference() {
        translate([0, 0, bowl_center_z])
            sphere(r = bowl_outer_r);
        // hollow interior
        translate([0, 0, bowl_center_z])
            sphere(r = bowl_inner_r);
        // remove upper half (everything above the rim)
        translate([-(bowl_outer_r + eps), -(bowl_outer_r + eps), bowl_center_z])
            cube([2 * (bowl_outer_r + eps),
                  2 * (bowl_outer_r + eps),
                  bowl_outer_r + eps]);
    }
}

module handle() {
    translate([handle_x_start, -handle_width / 2, handle_bot_z])
        cube([handle_x_end - handle_x_start, handle_width, handle_thick]);
}

difference() {
    union() {
        bowl();
        handle();
    }
    // keep the bowl cavity clear of any handle material
    translate([0, 0, bowl_center_z])
        sphere(r = bowl_inner_r);
}
