// Powder measuring scoop - hemispherical bowl with flat handle
// Print orientation: bowl bottom on bed (z = 0), opening upward

$fn = 96;

// ---------------- Parameters ----------------
bowl_r_out   = 15;      // outer radius of bowl sphere
bowl_wall    = 1.5;     // bowl wall thickness
bowl_r_in    = bowl_r_out - bowl_wall;  // inner radius (13.5)
bowl_cz      = 15;      // sphere centre height (rim height)

handle_x0    = 13.5;    // handle start in X
handle_x1    = 95;      // handle end in X
handle_w     = 12;      // handle width (Y)
handle_t     = 4;       // handle thickness (Z)
handle_ztop  = bowl_cz; // handle top flush with rim (z = 15)

eps          = 0.5;     // overlap for clean boolean cuts

// ---------------- Model ----------------
difference() {
    union() {
        // Lower half of outer sphere
        intersection() {
            translate([0, 0, bowl_cz])
                sphere(r = bowl_r_out);
            translate([-bowl_r_out - eps, -bowl_r_out - eps, -eps])
                cube([2 * (bowl_r_out + eps),
                      2 * (bowl_r_out + eps),
                      bowl_cz + eps]);
        }

        // Flat handle, top face flush with rim
        translate([handle_x0, -handle_w / 2, handle_ztop - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }

    // Hollow out the bowl cavity (extends above rim to avoid coplanar faces)
    translate([0, 0, bowl_cz])
        sphere(r = bowl_r_in);
    translate([0, 0, bowl_cz])
        cylinder(r = bowl_r_in, h = eps + 1);
}
