// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 2.5;  // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 8;    // knuckle diameter
knuckle_n   = 3;    // number of knuckles
knuckle_y   = 15;   // knuckle axis Y position
knuckle_h   = 4;    // knuckle axis height (Z)
knuckle_w   = plate_len / knuckle_n;  // width of each segment (15 mm)

// ---- Pin ----
pin_d       = 3;    // pin hole diameter

// ---- Misc ----
eps         = 0.5;  // cutter overshoot past faces

difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st and 3rd segments
        for (i = [0, 2]) {
            translate([-knuckle_w*i + knuckle_w/2 - knuckle_d/2,
                       knuckle_y,
                       knuckle_h])
                cylinder(d = knuckle_d, h = 10);
        }
    }

    // Pin holes through every knuckle
    for (i = [0, 2]) {
        translate([-knuckle_w*i + knuckle_w/2 - knuckle_d/2,
                   knuckle_y,
                   knuckle_h])
            translate([0, 0, -eps])
                cylinder(d = pin_d, h = plate_thk + 2*eps);
    }
}
