// Pin hinge leaf - one half of a 5-knuckle pin hinge
// Prints flat on the bed, plate at z = 0..3

$fn = 96;

// ---- Plate ----
plate_len   = 60;    // X length of leaf
plate_wid   = 25;    // Y width of leaf
plate_thk   = 3;     // Z thickness of plate

// ---- Knuckles ----
n_segments  = 5;                       // total knuckle segments along length
seg_len     = plate_len / n_segments;  // 12 mm per segment
knuckle_d   = 7;                       // knuckle outer diameter
knuckle_y   = plate_wid / 2;           // axis Y position (12.5, on +Y edge)
knuckle_z   = 3.5;                     // axis Z height (bottom of knuckle on bed)
knuckle_idx = [0, 2, 4];               // 1st, 3rd and 5th segments

// ---- Pin hole ----
pin_d       = 3;     // pin hole diameter
cut_ext     = 0.5;   // extra length so cuts pass through end faces

difference() {
    union() {
        // Flat plate centred on origin
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on segments 1, 3, 5
        for (i = knuckle_idx)
            translate([-plate_len / 2 + i * seg_len, knuckle_y, knuckle_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole through every knuckle along the common axis
    translate([-plate_len / 2 - cut_ext, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2 * cut_ext);
}
