// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // length of each grip-to-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
// grip outer edge is at x = +/- (half_gauge + transition_len)
cut_start  = half_gauge + transition_len;

difference() {
    // Main plate
    translate([-total_length / 2, -thickness / 2, 0])
        cube([total_length, thickness, thickness]);

    // Central gauge section (overlaps into transitions for a clean cut)
    translate([-cut_start, -gauge_width / 2, -1])
        cube([gauge_length + 2 * transition_len, gauge_width, thickness + 2]);

    // Grip sections at each end
    for (s = [-1, 1])
        translate([s * cut_start, -grip_width / 2, -1])
            cube([grip_length, grip_width, thickness + 2]);
}
