// Flat tensile test specimen (dog bone)
// Prints flat on the bed; symmetric about the origin in X and Y.

// ---------------- Dimensions (mm) ----------------
thickness      = 3;    // specimen thickness (Z)
total_length   = 120;  // overall length (X)
gauge_width    = 10;   // narrow gauge section width (Y)
gauge_length   = 40;   // gauge section length (X)
grip_width     = 19;   // grip section width (Y)
grip_length    = 25;   // grip section length (X), each end
trans_length   = 15;   // linear transition length (X), each side

// ---------------- Derived values ----------------
x_gauge = gauge_length / 2;                 // end of gauge (20)
x_trans = x_gauge + trans_length;           // end of transition (35)
x_end   = x_trans + grip_length;            // end of grip (60)
hg      = gauge_width / 2;                  // half gauge width
hw      = grip_width / 2;                   // half grip width

// Sanity check: segments must add up to the total length
assert(abs(2 * x_end - total_length) < 1e-6,
       "Segment lengths do not sum to total_length");

// ---------------- Outline (top view) ----------------
outline = [
    [-x_end,   -hw], [-x_trans, -hw], [-x_gauge, -hg],
    [ x_gauge, -hg], [ x_trans, -hw], [ x_end,   -hw],
    [ x_end,    hw], [ x_trans,  hw], [ x_gauge,  hg],
    [-x_gauge,  hg], [-x_trans,  hw], [-x_end,    hw]
];

// ---------------- Part ----------------
linear_extrude(height = thickness)
    polygon(outline);
