// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 15;    // length of each grip-to-gauge transition

// ---- Derived ----
half_gauge = gauge_length / 2;
x0 = grip_length + transition_len + half_gauge;  // gauge start from left grip edge

// ---- Model ----
difference() {
    union() {
        // Left grip
        translate([-total_length / 2, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
        // Right grip
        translate([total_length / 2 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
        // Gauge section
        translate([-x0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Transitions (linear width change: grip -> gauge)
        for (s = [-1, 1])
            translate([s > 0 ? x0 - transition_len : -x0 + transition_len,
                       -grip_width / 2, 0])
                linear_extrude(thickness)
                    polygon([for (t = [0 : 0.01 : 1])
                        [s > 0 ? x0 - transition_len * (1 - t) : -x0 + transition_len * (1 - t),
                         grip_width * (1 - t) / 2],
                         for (t = [0.99 : -0.01 : 0])
                            [s > 0 ? x0 - transition_len * (1 - t) : -x0 + transition_len * (1 - t),
                             grip_width * (1 - t) / 2]]);
    }
    // Optional: small central hole to avoid coplanar faces
    translate([0, 0, -1])
        cylinder(h = thickness + 2, d = 0.5);
}
