half_grip   = grip_w / 2;
half_gauge  = gauge_w / 2;
reach       = grip_len + trans_len;   // end of grip from centre

// ---------- Model ----------
difference() {
    // Main plate
    translate([-total_len / 2, -thickness / 2, 0])
        cube([total_len, thickness, 100]);

    // Central gauge section
    translate([-gauge_len / 2, -half_gauge, -eps])
        cube([gauge_len, gauge_w, thickness + 2 * eps]);

    // Grip sections at each end
    for (s = [-1, 1])
        translate([s * reach, -half_grip, -eps])
            cube([grip_len, grip_w, thickness + 2 * eps]);

    // Transition regions (15 -> 8 mm width)
    for (s = [-1, 1]) {
        x0 = s > 0 ? gauge_len / 2 : -gauge_len / 2;
        w0 = 15;
        w1 = 8;
        translate([x0 - trans_len, -thickness / 2, 0])
            linear_extrude(height = thickness)
                polygon([
                    [0, w0 / 2],
                    [trans_len, w1 / 2],
                    [trans_len, -w1 / 2],
                    [0, -w0 / 2]
                ]);
    }
}
