    cylinder(d = wheel_d, h = rim_w);

    // Hub with axle hole
    translate([0, 0, -eps])
        difference() {
            cylinder(d = hub_d, h = rim_w + 2 * eps);
            translate([0, 0, -eps])
                cylinder(d = axle_hole_d, h = rim_w + 2 * eps + 2);
        }

    // Spokes, radially from hub to rim
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start + i * 360 / spoke_count;
        translate([hub_d / 2 - 1, 0, -eps])
            rotate([0, 0, a])
                difference() {
                    translate([0, -spoke_w / 2, 0])
                        cube([spoke_w, spoke_w, rim_w + 2 * eps]);
                    // remove overlap into hub (0.5 mm clearance)
                    translate([0, -spoke_w / 2, -eps])
                        cube([hub_d / 2 - 1, spoke_w, rim_w + 2 * eps + 2]);
                }
    }
