part_thickness   = 5;     // part thickness (Z)
outer_diameter   = 60;    // outer rim diameter
rim_width        = 5;     // rim width (radial)
hub_diameter     = 16;    // hub diameter
axle_hole_d      = 5;     // axle hole diameter
spoke_count      = 4;     // number of spokes
spoke_width      = 4;     // spoke width (radial and tangential)
