        // Hub
        translate([0, 0, -eps])
            cylinder(d = hub_d, h = wheel_w + 2 * eps);

        // Spokes: radial blocks from hub to rim
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start + i * 360 / spoke_count;
            translate([0, 0, -eps])
                rotate([0, 0, a])
                    translate([hub_d / 2 - 1, -spoke_w / 2, 0])
                        cube([spoke_w, spoke_w, wheel_w + 2 * eps]);
        }
    }

    // Axle hole through the centre
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = wheel_w + 2 * eps, $fn = 64);
