// Stiffened cover panel
// Units: mm. Print orientation: plate on bed, ribs upward.

plate_len   = 100;  // plate length (X)
plate_wid   = 50;   // plate width (Y)
plate_thk   = 3;    // plate thickness (Z)

rib_count   = 3;    // number of ribs
rib_thk     = 3;    // rib thickness (X)
rib_hgt     = 6;    // rib height above plate (Z)
rib_pitch   = plate_len / (rib_count + 1); // 25 mm spacing between rib centres

overlap     = 0.01; // small overlap so ribs fuse with the plate

union() {
    // Base plate, centred in X and Y, z = 0..3
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, full width along Y, z = 3..9
    for (i = [1 : rib_count]) {
        x_c = -plate_len/2 + i * rib_pitch; // -25, 0, 25
        translate([x_c - rib_thk/2, -plate_wid/2, plate_thk - overlap])
            cube([rib_thk, plate_wid, rib_hgt + overlap]);
    }
}
