// Cable bridge - rectangular block with 3 semicircular tunnels along Y at floor level
// Print orientation: base on XY plane (z = 0), tunnels open downward

// ---------------- Parameters ----------------
block_len   = 80;    // block length along X (mm)
block_wid   = 50;    // block width along Y (mm)
block_ht    = 15;    // block height along Z (mm)

tunnel_d    = 8;     // tunnel cylinder diameter (mm)
tunnel_pitch = 16;   // centre-to-centre spacing of tunnel axes along X (mm)
tunnel_n     = 3;    // number of tunnels

eps         = 0.5;   // overcut so cutting faces are not coplanar (mm)

$fn = 96;            // curve resolution

// ---------------- Derived ----------------
tunnel_r = tunnel_d / 2;
// first tunnel axis at x = - (n-1)*pitch/2, then step by +pitch
function tunnel_x(i) = (i - (tunnel_n - 1) * tunnel_pitch / 2) * tunnel_pitch;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnels: cylinder axis along Y at z = 0,
    // extended eps above and below so the cut is clean
    for (i = [0 : tunnel_n - 1])
        translate([tunnel_x(i), 0, -eps])
            rotate([0, 90, 0])
                cylinder(h = block_wid + 2 * eps, r = tunnel_r);
}
