difference() {
    // Body
    union() {
        // Grip sections
        for (s = [-1, 1])
            translate([s > 0 ? grip_l - transition_l : -grip_l, -grip_w / 2, 0])
                cube([grip_l + transition_l, grip_w, specimen_t]);
        // Gauge section
        translate([-gauge_l / 2, -gauge_w / 2, 0])
            cube([gauge_l, gauge_w, specimen_t]);
        // Transitions (linear width change)
        for (s = [-1, 1])
            translate([s > 0 ? grip_l - transition_l : -grip_l, 0, 0])
                linear_extrude(height = specimen_t)
                    polygon([
                        [0, -grip_w / 2],
                        [transition_l, -grip_w / 2],
                        [transition_l, grip_w / 2],
                        [0, grip_w / 2]
                    ]);
    }

    // Optional through-hole in gauge section for alignment
    translate([-gauge_l / 2, 0, -1])
        cylinder(d = 3, h = gauge_l + 2);
}
