trans_x1 = trans_x0 + transition_len;          // transition end X

// ---- Width profile (seen from above) ----
function width(x) =
    if (x < trans_x0) grip_width
    else if (x <= gauge_x0) linear_map(x, trans_x0, gauge_x0, grip_width, gauge_width)
    else if (x <= trans_x1) linear_map(x, gauge_x0, trans_x1, gauge_width, grip_width)
    else grip_width;

difference() {
    // Main plate
    translate([-total_length / 2, -thickness / 2, 0])
        linear_extrude(thickness)
            polygon([for (sx = [-1, 1]) for (sy = [-1, 1])
                [sx * (total_length / 2 - grip_length + 1),
                 sy * thickness / 2 + thickness / 3]]);

    // Central gauge section (overlaps slightly into transitions for clean cut)
    translate([gauge_x0 - 1, -gauge_width / 2, 0])
        cube([gauge_length + 2, gauge_width, thickness]);
