half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// centre of each region so the whole part is centred on origin
x0_gauge   = -half_grip - trans_len - half_gauge;
x0_trans   = -half_grip - trans_len / 2;
x0_grip    = half_gauge + trans_len / 2;

// ---------- Model ----------
module dogbone() {
    difference() {
        translate([-total_len / 2, -thickness / 2, 0])
            linear_extrude(height = thickness)
                polygon(points = [
                    [x0_grip + grip_len, -grip_w / 2],
                    [x0_grip + grip_len,  grip_w / 2],
                    [x0_trans + trans_len,  grip_w / 2],
                    [x0_trans,              grip_w / 2],
                    [x0_trans,             -grip_w / 2],
                    [x0_trans + trans_len, -grip_w / 2],
                    [x0_gauge - half_gauge, -gauge_w / 2],
                    [x0_gauge - half_gauge,  gauge_w / 2],
                    [x0_gauge + half_gauge,  gauge_w / 2],
                    [x0_gauge + half_gauge, -gauge_w / 2],
                    [x0_trans - trans_len, -grip_w / 2],
                    [x0_trans - trans_len,  grip_w / 2]
                ]);
    }
}

