// Print orientation: bowl bottom on the bed (z = 0), handle on top, opening upward.

$fn = 96;

// ---- Bowl ----
outer_radius   = 15;    // mm, outer radius of the sphere
wall_thickness = 2;     // mm, wall thickness of the bowl
rim_z          = 15;    // mm, z of the rim (sphere centre height)
bottom_z       = 0;     // mm, z where the bowl touches the bed

