block_wid    = 40;    // block width along Y (mm)
block_h      = 12;    // block height along Z (mm)

tunnel_d     = 12;    // tunnel diameter (mm); radius = 6 mm
tunnel_count = 3;     // number of tunnels
tunnel_pitch = 16;    // centre-to-centre spacing of tunnels along X (mm)

