// first tunnel axis X position, with the row centred on the origin
tunnel_x0 = -(tunnel_count - 1) * tunnel_pitch / 2;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // Semicircular tunnels: cylinder axes along Y at z = 0,
    // running from the negative to the positive X face
    for (i = [0 : tunnel_count - 1])
        translate([tunnel_x0 + i * tunnel_pitch, 0, 0])
            translate([0, 0, 0])
                cylinder(r = tunnel_r, h = block_len + 2 * eps, $fn = 96);
