// Star-shaped indexing wheel (8-pointed), printed flat on the bed

// ---- Parameters ----
n_points   = 8;     // number of star points
r_outer    = 30;    // radius of outer (tip) points, mm
r_inner    = 18;    // radius of inner (valley) points, mm
thickness  = 4;     // plate thickness, mm
hole_d     = 8;     // centre hole diameter, mm
eps        = 0.5;   // cutter overshoot past faces, mm
$fn        = 96;    // resolution for curved shapes

// ---- Star outline: alternating outer/inner vertices, first outer on +X ----
function star_pts(n, ro, ri) =
    [ for (i = [0 : 2*n - 1])
        let (a = i * 180 / n,
             r = (i % 2 == 0) ? ro : ri)
        [ r * cos(a), r * sin(a) ] ];

// ---- Part ----
difference() {
    linear_extrude(height = thickness)
        polygon(star_pts(n_points, r_outer, r_inner));

    // centre hole, extends past top and bottom faces
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2*eps, $fn = 96);
}
