top_area       = top_size * top_size;        // top face area (mm2)
// Frustum volume (mm3)
block_volume   = (base_area + top_area + sqrt(base_area * top_area)) * height / 3;
// Material removed for pocket (mm3)
pocket_volume  = pocket_w * pocket_w * pocket_d;
// Net mass proxy (g), assuming 1 g/mm3
mass_g         = block_volume - pocket_volume;

// ---------------- Model ----------------
difference() {
    // Tapered block: hull between bottom and top faces, centred in X/Y
    hull() {
        translate([-base_size / 2, -base_size / 2, 0])
            cube([base_size, base_size, 0]);
        translate([-top_size / 2, -top_size / 2, height])
            cube([top_size, top_size, height]);
    }

    // Square pocket cut into the top face, centred
    translate([-pocket_w / 2, -pocket_w / 2, pocket_floor_z])
        cube([pocket_w, pocket_w, height - pocket_floor_z + eps]);
