// ---- Dimensions (mm) ----
thickness    = 4;    // specimen thickness (Z)
total_length = 140;  // overall length (X)
gauge_width  = 6;    // width of narrow gauge section (Y)
gauge_length = 40;   // length of gauge section (X)
grip_width   = 15;   // width of grip sections (Y)
grip_length  = 35;   // length of each grip section (X)
trans_length = 15;   // length of each linear transition (X)

// ---- Derived X stations (positive side) ----
x_gauge = gauge_length / 2;                 // end of gauge section  (20)
x_trans = x_gauge + trans_length;           // end of transition     (35)
x_end   = x_trans + grip_length;            // end of grip           (70)

// Sanity check: should equal total_length / 2
echo(str("Computed half length = ", x_end, ", expected = ", total_length / 2));

gw = gauge_width / 2;  // half gauge width
pw = grip_width / 2;   // half grip width

// ---- Outline seen from above (counter-clockwise) ----
outline = [
    [ x_end,  -pw], [ x_end,   pw],
    [ x_trans, pw], [ x_gauge, gw],
    [-x_gauge, gw], [-x_trans, pw],
    [-x_end,   pw], [-x_end,  -pw],
    [-x_trans,-pw], [-x_gauge,-gw],
    [ x_gauge,-gw], [ x_trans,-pw]
];

// ---- Part ----
linear_extrude(height = thickness)
    polygon(points = outline);
