// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 140;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // length of each grip-to-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
// grip outer edge is at x = +/- (half_gauge + transition_len)
outer_x    = half_gauge + transition_len;

difference() {
    // Main body
    translate([-total_length / 2, -thickness / 2, 0])
        linear_extrude(thickness)
            polygon([
                [-outer_x, -grip_width / 2],
                [ outer_x, -grip_width / 2],
                [ outer_x,  grip_width / 2],
                [ half_gauge, grip_width / 2],
                [ half_gauge, -gauge_width / 2],
                [-half_gauge, -gauge_width / 2],
                [-half_gauge, grip_width / 2],
                [-outer_x,  grip_width / 2]
            ]);

    // Remove the central gauge section, leaving a thin wall
    translate([-half_gauge - 0.5, -gauge_width / 2 - 0.5, -1])
        cube([gauge_length + 1, gauge_width + 1, thickness + 2]);
}
