gauge_length   = 40;   // length of gauge section (X)
grip_width     = 15;   // width of grip sections (Y)
grip_length    = 35;   // length of each grip section (X)
trans_length   = 10;   // length of each linear transition (X)

// Derived positions along X (from centre)
x_gauge = gauge_length / 2;            // 20: end of gauge section
x_trans = x_gauge + trans_length;      // 30: end of transition
x_end   = x_trans + grip_length;       // 65: specimen end

// Sanity check: section lengths should add up to the total length
assert(abs(2 * x_end - total_length) < 1e-6,
       "Section lengths do not add up to total_length");

hg = gauge_width / 2;  // half gauge width
hw = grip_width / 2;   // half grip width

// ---------------- Outline (top view) ----------------
outline = [
    [-x_end,   -hw], [-x_trans, -hw], [-x_gauge, -hg],
    [ x_gauge, -hg], [ x_trans, -hw], [ x_end,   -hw],
    [ x_end,    hw], [ x_trans,  hw], [ x_gauge,  hg],
    [-x_gauge,  hg], [-x_trans,  hw], [-x_end,    hw]
];

// ---------------- Part ----------------
linear_extrude(height = thickness)
    polygon(outline);
