// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
// grip outer edge is transition_len away from gauge outer edge
x0 = -half_gauge - transition_len - grip_length / 2;  // left grip start
x1 =  half_gauge + transition_len + grip_length / 2;  // right grip end

// ---- Profile (seen from above) ----
module profile() {
    hull() {
        // left grip
        translate([x0, -grip_width / 2]) square([grip_length, grip_width]);
        // right grip
        translate([x1 - grip_length, -grip_width / 2]) square([grip_length, grip_width]);
        // gauge section
        translate([-half_gauge, -gauge_width / 2]) square([gauge_length, gauge_width]);
    }
}

difference() {
    // plate
    linear_extrude(thickness) profile();

    // cut out the transition regions so the hull follows a straight
    // width change (15 -> 10) without extra hull facets
    for (s = [-1, 1]) {
        tx = s * (half_gauge + transition_len / 2);
        translate([tx - transition_len, -grip_width])
            linear_extrude(thickness + 2)
                polygon([[-transition_len, -grip_width / 2],
                         [-transition_len, grip_width / 2],
                         [transition_len, grip_width / 2],
                         [transition_len, -grip_width / 2]]);
    }
}
