    union() {
        for (sx = [-1, 1]) {
            translate([sx * outer_x, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
        }
        for (sx = [-1, 1]) {
            translate([sx * (outer_x - transition_len), -gauge_width / 2, 0])
                cube([gauge_length, gauge_width, thickness]);
