    // Cut the transition regions, which run from grip width down to gauge width
    for (sx = [-1, 1]) {
        translate([sx * (outer_x - transition_len), 0, 0])
            rotate([90, 0, 0])
                linear_extrude(height = thickness)
                    polygon([
                        [0, grip_width / 2],
                        [transition_len, grip_width / 2],
                        [transition_len, gauge_width / 2],
                        [0, gauge_width / 2]
                    ]);
        translate([sx * (outer_x - transition_len), 0, 0])
            rotate([90, 0, 0])
                linear_extrude(height = thickness)
                    polygon([
                        [0, -grip_width / 2],
                        [transition_len, -grip_width / 2],
                        [transition_len, -gauge_width / 2],
                        [0, -gauge_width / 2]
