$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 110;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
// grip outer edge is transition_len away from gauge outer edge
x0 = -half_gauge - transition_len - grip_length / 2;  // left grip start
x1 =  half_gauge + transition_len + grip_length / 2;  // right grip end

// ---- Width profile (seen from above) ----
function width(x) =
    if (x < x0 + grip_length / 2) grip_width
    else if (x < x0 + grip_length + transition_len)
        grip_width + (gauge_width - grip_width) *
            (x - (x0 + grip_length / 2)) / transition_len
    else if (x < x1 - transition_len - grip_length)
        gauge_width
    else if (x < x1 - grip_length - transition_len / 2)
            gauge_width + (grip_width - gauge_width) *
                (x - (x1 - grip_length - transition_len)) / transition_len
        else grip_width;

difference() {
    // Main plate
    translate([-x1, -thickness / 2, 0])
        rotate([90, 0, 0])
            linear_extrude(thickness)
                polygon(points = [for (i = [0 : 100]) [x0 + i * (x1 - x0) / 100, width(x0 + i * (x1 - x0) / 100)]]);

    // Central relief to keep the gauge section at the stated width
    translate([-half_gauge - transition_len - grip_length / 2 - 1,
               -gauge_width / 2 - 1, 0])
        cube(gauge_length + 2 * transition_len + 2 * grip_length / 2,
             gauge_width + 2, thickness + 2);
