        translate([0, 0, -cut_extra])
            cylinder(d = hub_diameter, h = wheel_thickness + 2 * cut_extra);

        // Radial spokes, first along +X axis
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_r, -spoke_width / 2, -cut_extra])
                    cube([outer_r - hub_r, spoke_width, wheel_thickness + 2 * cut_extra]);
    }

    // Axle hole through the centre
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = wheel_thickness + 2 * cut_extra);
