    union() {
        // Bottom flange: z = 0 .. flange_thick
        translate([-length_x / 2, -flange_width / 2, 0])
            cube([length_x, flange_width, flange_thick]);

        // Neck: centred on origin in X and Y, z = 0 .. neck_top_z
        translate([-neck_width / 2, -neck_width / 2, 0])
            cube([neck_width, neck_width, neck_top_z]);
    }

    // Vertical through-hole for screw
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + 2 * eps);
}
