            sphere(r = outer_radius);
        translate([0, 0, rim_z - wall_thickness - cut_extra])
            sphere(r = outer_radius - wall_thickness);
        // keep only lower half (z <= rim_z), discarding the upper half
        translate([0, 0, -1000])
            cube([outer_radius * 2, wall_thickness * 2, 2 * rim_z]);
