        translate([0, 0, bowl_outer_radius + cut_extra])
            sphere(r = bowl_inner_radius + cut_extra);
    }
    // Keep only the lower half of the sphere (z <= 15)
    translate([0, 0, -bowl_outer_radius])
        hull() {
            sphere(r = bowl_outer_radius, $fn = 96);
            translate([0, 0, bowl_outer_radius])
                sphere(r = bowl_outer_radius, $fn = 96);
        }
    // The hull above gives a full sphere centred at origin; shift it so
    // the upper half is discarded and the bottom touches z = 0.
    translate([0, 0, bowl_outer_radius])
        hull() {
            translate([0, 0, -bowl_outer_radius])
                sphere(r = bowl_outer_radius, $fn = 96);
            translate([0, 0, bowl_outer_radius])
                sphere(r = bowl_outer_radius, $fn = 96);
        }

    // Flat handle along +X, centred on y = 0, top face at z = 15
    translate([handle_start_x, -handle_width / 2, handle_top_z - handle_thickness])
        cube([handle_end_x - handle_start_x, handle_width, handle_thickness]);
