// Cable bridge - rectangular block with 3 semicircular tunnels along Y at floor level
// Print orientation: base on the bed (z = 0), tunnels open downward

// ---------------- Parameters ----------------
block_len    = 60;    // block length along X (mm)
block_wid    = 30;    // block width along Y (mm)
block_ht     = 12;    // block height along Z (mm)

tunnel_d     = 12;    // tunnel diameter (mm); radius = 6 mm
tunnel_count = 3;     // number of tunnels
tunnel_pitch = 20;    // centre-to-centre spacing of tunnels along X (mm)
tunnel_r     = tunnel_d / 2;  // tunnel radius (mm)

eps          = 0.5;   // overcut so cutters pass beyond the faces they cut (mm)

$fn = 96;             // curve resolution

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnels: cylinder axes lie along Y at z = 0,
    // centred along X with the given pitch
    for (i = [0 : tunnel_count - 1]) {
        x_c = (i - (tunnel_count - 1) / 2) * tunnel_pitch;
        translate([x_c, 0, 0])
            rotate([90, 0, 0])
                cylinder(h = block_wid, r = tunnel_r, $fn = 96);
    }
}
