// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 40;    // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle diameter
knuckle_n   = 5;     // number of segments along length
knuckle_x0  = -plate_len/2; // first segment centre X
knuckle_y   = 15;    // knuckle axis Y position
knuckle_z   = 3;     // knuckle axis height above bed
pin_d       = 2.5;   // pin hole diameter

// ---- Helpers ----
eps         = 0.5;   // cutter overshoot past faces
pitch       = plate_len / knuckle_n; // 8 mm segment length
knuckle_ks  = [for (i = [0:knuckle_n-1]) if (i % 2 == 0) 1 else 0]; // 1st,3rd,5th

difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders
        for (i = [0:knuckle_n-1])
            if (knuckle_ks[i])
                translate([knuckle_x0 + i*pitch, knuckle_y, knuckle_z])
                    cylinder(d = knuckle_d, h = 10, $fn = 64);
    }

    // Pin holes through every knuckle
    for (i = [0:knuckle_n-1])
        if (knuckle_ks[i])
            translate([knuckle_x0 + i*pitch, knuckle_y, knuckle_z])
                cylinder(d = pin_d, h = 10, $fn = 64);
}
