shaft_h      = hub_h + eps;     // shaft hole extends into hub

// ---------------- Model ----------------
difference() {
    union() {
        // Cam disc
        translate([cam_x, 0, 0])
            cylinder(d = cam_d, h = cam_t);

        // Shaft hub (overlaps disc slightly for a clean union)
        translate([0, 0, cam_t - eps])
            cylinder(d = hub_d, h = hub_h + eps);
    }

    // Shaft through-hole: separate top and bottom cuts to avoid coplanar faces
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = hub_h + 2 * eps);   // through hub
    translate([0, 0, cam_t])
        cylinder(d = shaft_d, h = eps);               // into disc
