    for (i = [0 : 2 * n_points - 1])
        let (a = i * 180 / n_points,
             r = (i % 2 == 0) ? r_outer : r_inner)
        [r * cos(a), r * sin(a)]
];

difference() {
    linear_extrude(height = thickness)
        polygon(star_pts);

    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
