// Units: mm

base_size    = 60;   // bottom square side length (z = 0)
top_size     = 20;   // top square side length (z = block_height)
block_height = 20;   // overall height of frustum

pocket_size  = 10;   // square pocket side length
pocket_depth = 5;    // pocket depth from top face

eps = 0.5;           // overlap for clean boolean cuts

difference() {
    // Square frustum built from 8 vertices
    polyhedron(
        points = [
            // bottom square (z = 0)
            [-base_size/2, -base_size/2, 0],
            [ base_size/2, -base_size/2, 0],
            [ base_size/2,  base_size/2, 0],
            [-base_size/2,  base_size/2, 0],
            // top square (z = block_height)
            [-top_size/2, -top_size/2, block_height],
            [ top_size/2, -top_size/2, block_height],
            [ top_size/2,  top_size/2, block_height],
            [-top_size/2,  top_size/2, block_height]
        ],
        faces = [
            [0, 1, 2, 3],  // bottom
            [4, 5, 1, 0],  // front (-Y)
            [5, 6, 2, 1],  // right (+X)
            [6, 7, 3, 2],  // back (+Y)
            [7, 4, 0, 3],  // left (-X)
            [7, 6, 5, 4]   // top
        ]
    );

    // Centred square pocket in the top face
    translate([-pocket_size/2, -pocket_size/2, block_height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
