// Cabinet door pull handle
// Print orientation: posts stand on the bed (z = 0), bar on top.

// ---------------- Parameters ----------------
post_d      = 14;    // post diameter
post_h      = 25;    // post height (z = 0 to 25)
post_x      = 32;    // post centre offset from origin (+/-)
bar_len     = 78;    // bar length along X
bar_w       = 14;    // bar width along Y
bar_t       = 8;     // bar thickness (z = 25 to 33)
screw_d     = 4.5;   // screw hole diameter
screw_depth = 10;    // screw hole depth from bottom face
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------------- Model ----------------
union() {
    // Two round posts
    for (sx = [-1, 1])
        translate([sx * post_x, 0, 0])
            cylinder(d = post_d, h = post_h);

    // Straight bar, centred on origin, overlapping posts slightly
    translate([-bar_len / 2, -bar_w / 2, post_h - eps])
        cube([bar_len, bar_w, bar_t + eps]);

    // Screw holes in each post, from bottom face upward along axis
    for (sx = [-1, 1])
        translate([sx * post_x, 0, -eps])
            cylinder(d = screw_d, h = post_h + eps + screw_depth);
}
