x_end   = x_trans + grip_length;            // 65 (= total_length/2)

hg = gauge_width / 2;   // half gauge width
hw = grip_width / 2;    // half grip width

// Sanity check of the overall length
echo(str("Computed total length = ", 2 * x_end, " mm (spec ", total_length, " mm)"));

// Top-view outline, symmetric about origin, traced counter-clockwise
outline = [
    [ x_end, -hw], [ x_end,  hw],
    [ x_trans,  hw], [ x_gauge,  hg],
    [-x_gauge,  hg], [-x_trans,  hw],
    [-x_end,  hw], [-x_end, -hw],
    [-x_trans, -hw], [-x_gauge, -hg],
    [ x_gauge, -hg], [ x_trans, -hw]
];

linear_extrude(height = thickness)
    polygon(points = outline);
