```openscad
// Flat tensile test specimen (dog bone) for printed plastic
// Lies flat on the bed, symmetric about the origin, length along X

// ---- Dimensions (mm) ----
thickness      = 3;    // specimen thickness (Z)
total_length   = 130;  // overall length (X)
gauge_width    = 10;   // gauge section width (Y)
gauge_length   = 40;   // gauge section length (X)
grip_width     = 19;   // grip section width (Y)
grip_length    = 30;   // grip section length at each end (X)
trans_length   = 15;   // linear transition length at each side (X)

// ---- Derived values ----
x_gauge = gauge_length / 2;                 // end of gauge section (20)
x_trans = x_gauge + trans_length;           // end of transition (35)
x_end   = x_trans + grip_length;            // end of grip (65)
hg      = gauge_width / 2;                  // half gauge width
hw      = grip_width / 2;                   // half grip width

// Sanity check: segments must add up to the total length
assert(abs(2 * x_end - total_length) < 1e-6,
       "Segment lengths do not sum to total_length");

