$fn = 64;

// ---- Dimensions (mm) ----
nut_length     = 12;    // length along X (slot direction)
flange_width   = 14;    // bottom flange width (Y)
flange_thick   = 2.5;   // flange thickness, z = 0 .. 2.5
neck_width     = 7;     // neck width (Y), centred
total_height   = 5.5;   // top of neck (z)
hole_d         = 3.4;   // vertical screw clearance hole diameter
eps            = 0.5;   // cutter overshoot past faces

neck_height = total_height - flange_thick; // neck height above flange

difference() {
    union() {
        // Bottom flange
        translate([-nut_length/2, -flange_width/2, 0])
            cube([nut_length, flange_width, flange_thick]);

        // Centred neck
        translate([-nut_length/2, -neck_width/2, flange_thick - 0.01])
            cube([nut_length, neck_width, neck_height + 0.01]);
    }

    // Vertical screw hole through the centre
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = total_height + 2*eps);
}
```

