// Powder measuring scoop
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle along +X.

// ---------- Parameters ----------
sphere_r      = 10;    // outer radius of spherical bowl
wall          = 2;     // bowl wall thickness
handle_w      = 12;    // handle width (Y)
handle_t      = 3;     // handle thickness (Z)
handle_x0     = 8;     // handle start (X)
handle_x1     = 90;    // handle end (X)
cut_extra     = 0.5;   // overshoot for clean boolean cuts
$fn           = 96;    // curve resolution

// ---------- Derived ----------
rim_z = sphere_r;      // rim height (lower hemisphere: centre at z = r, rim at z = 2r -> adjusted per spec)
// Per spec: bottom at z = 0, rim at z = 10, wall 2 mm -> inner radius 8 mm
inner_r = sphere_r - wall;

// ---------- Model ----------
union() {
    // Hollow spherical bowl (lower half)
    translate([0, 0, wall])
        difference() {
            sphere(r = sphere_r);
            translate([0, 0, -cut_extra])
                sphere(r = inner_r + 2 * cut_extra);
        }
    // Clip to keep only the lower half so the bottom touches z = 0
    translate([0, 0, -cut_extra])
        difference() {
            hull() {
                translate([0, 0, cut_extra]) sphere(r = wall + 0.01);
                translate([0, 0, sphere_r]);
            }
        }

    // Flat handle, top face flush with rim (z = 10)
    translate([handle_x0, -handle_w / 2, rim_z - handle_t])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}
