// Powder measuring scoop
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle along +X.

// ---------- Parameters ----------
sphere_r      = 10;    // outer radius of spherical bowl
wall          = 2;     // bowl wall thickness
handle_w      = 8;     // handle width (Y)
handle_t      = 4;     // handle thickness (Z)
handle_x0     = 8;     // handle start (X)
handle_x1     = 110;   // handle end (X)
