// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 40;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

knuckle_n     = 5;   // number of knuckle segments
knuckle_pitch = 8;   // centre-to-centre spacing along X
knuckle_d     = 7;   // knuckle diameter
knuckle_z     = 3.5; // knuckle axis height above bed

pin_d         = 2;   // pin hole diameter

eps           = 0.5; // cutter overshoot past faces
$fn           = 96;  // curve resolution

// ---------- Derived ----------
knuckle_h = knuckle_d + 2*eps;   // total knuckle height (diameter + overshoot)

// ---------- Model ----------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on 1st, 3rd, 5th segments (odd indices)
    for (i = [0 : knuckle_n - 1]) {
        if (i % 2 == 0) {
            x = (i - (knuckle_n - 1)/2) * knuckle_pitch;
            translate([x, 12.5, 0])
                cylinder(d = knuckle_d, h = knuckle_h);
        }
    }

    // Pin hole along the knuckle axis, through every knuckle
    translate([0, 12.5, -eps])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
