knuckle_y   = 10;    // knuckle axis Y position (on +Y edge)
knuckle_z   = 4;     // knuckle axis height above bed

// ---- Pin ----
pin_d       = 2.5;   // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (i = [0, 2, 4]) {
            translate([knuckle_x0 + i*knuckle_pitch, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = 10, $fn = 64);
