// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
outer_r   = 35;    // distance of outer points from centre
inner_r   = 17.5;  // distance of inner points from centre
points    = 5;     // number of points (and inner points)
thickness = 4;     // plate thickness
hole      = 8;     // central through-hole diameter
eps       = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---- Model ----
difference() {
    // Star outline: outer points at 0, 72, ... deg; inner points at 36, 108, ...
    hull() {
        for (i = [0 : points - 1]) {
            rotate([0, 0, i * 360 / points])
                translate([0, 0, 0])
                    union() {
                        // outer point
                        translate([outer_r, 0, 0])
                            cube([outer_r, 2 * outer_r, thickness]);
                        // inner point
                        translate([inner_r, 0, 0])
                            cube([inner_r, 2 * inner_r, thickness]);
                    }
        }
    }
    // central hole, extends past top and bottom faces
    translate([0, 0, -eps])
        cylinder(d = hole, h = thickness + 2 * eps);
}
