// Tapered riser block for a beaker, with a square pocket in the top face
// Print orientation: flat on the bed, bottom face at z = 0

// ---------------- Parameters ----------------
block_bottom   = 100;   // side length of the square at z = 0 (mm)
block_top      = 70;    // side length of the square at z = 30 (mm)
block_height   = 30;    // total height of the frustum (mm)

pocket_size    = 62;    // side length of the square pocket (mm)
pocket_depth   = 8;     // depth of the pocket from the top face (mm)

eps            = 0.5;   // overshoot for clean boolean cuts (mm)
$fn            = 64;    // curve resolution (no curves here; kept per convention)

// ---------------- Derived ----------------
// Slope factor: how much the side length changes per mm of height
block_slope = (block_bottom - block_top) / block_height;   // 1 mm/30 mm = 0.0333 mm/mm

// ---------------- Model ----------------
difference() {
    // Solid square frustum: sides run parallel to X and Y from z = 0 to z = 30
    hull() {
        for (z = [0 : block_height]) {
            side = block_bottom - block_slope * z;
            translate([-side / 2, -side / 2, z])
                cube([side, side, 1]);   // 1 mm thick slice, fused by hull()
        }
    }

    // Square pocket centred on the top face, open at the top
    translate([-pocket_size / 2, -pocket_size / 2, block_height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
