// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 4;     // specimen thickness (Z)
total_len   = 130;   // overall length along X
gauge_w     = 8;     // gauge section width (Y)
gauge_len   = 40;    // gauge section length (X)
grip_w      = 19;    // grip section width (Y)
grip_len    = 30;    // grip section length (X)
trans_len   = 15;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// centre of each region so the whole part is centred on origin
x0_gauge   = -half_grip - trans_len - half_gauge;
x0_grip    = -half_grip - trans_len + half_grip;   // inner grip end
x0_trans   = -half_grip;
x0_grip_r  = half_gauge + trans_len - half_grip;   // outer grip end

// ---------- Model ----------
difference() {
    union() {
        // gauge
        translate([x0_gauge, -gauge_w / 2, 0])
            cube([gauge_len, gauge_w, thickness]);
        // grips
        for (s = [-1, 1])
            translate([x0_grip_r * s, -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness]);
        // transitions (width changes linearly from grip_w to gauge_w)
        for (s = [-1, 1])
            translate([x0_trans * s, -trans_w(s) / 2, 0])
                cube([trans_len, trans_w(s), thickness]);
    }
    // remove a central core so the outer grip stays taut during testing
    translate([-total_len / 2 - eps, -gauge_w / 2 - eps, -eps])
        cube([total_len + 2 * eps, gauge_w + 2 * eps, thickness + 2 * eps]);
}

// ---------- Helpers ----------
function trans_w(t) = grip_w + (gauge_w - grip_w) * (t + trans_len / 2) / trans_len;
```

```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 15;    // length of each grip-to-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
half_grip  = grip_length / 2;
// Check: gauge + 2*transition + 2*grip = 40 + 30 + 30 = 100;
// user stated total 130, so 30 mm are unaccounted for.
// Placing grip sections at each end leaves a central gap of 100 mm.
// To keep the stated lengths, centre the whole part on the origin.
overhang = total_length - (gauge_length + 2 * transition_len + 2 * grip_length); // 30 mm

module dog_bone() {
    difference() {
        // Upper surface
        linear_extrude(height = thickness)
            hull() {
                for (s = [-1, 1]) {
                    translate([s * (half_gauge + transition_len + half_grip) + overhang / 2,
                               -grip_width / 2]) square([grip_length, grip_width]);
                    translate([s * (half_gauge + transition_len / 2),
                               -gauge_width / 2]) square([gauge_length, gauge_width]);
                }
            }
        // Cut out the lower half, leaving a solid plate
        translate([0, 0, -1]) cube([total_length, grip_width * 2 + 4, 1]);
    }
}

dog_bone();
