```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 3;     // specimen thickness (Z)
total_len   = 120;   // overall length along X
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 30;    // gauge section length (X)
grip_w      = 15;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 10;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_grip   = grip_w / 2;
half_gauge  = gauge_w / 2;
reach       = grip_len + trans_len;   // distance from origin to grip end
area        = gauge_w * thickness;    // gauge cross-section area

// ---------- Model ----------
difference() {
    // Outer solid
    hull() {
        // Grip sections
        for (s = [-1, 1])
            translate([s * reach, -half_grip, 0])
                cube([grip_len, grip_w, thickness]);
    }

    // Gauge section
    translate([-gauge_len / 2, -half_gauge, 0])
        cube([gauge_len, gauge_w, thickness]);

    // Transition sections (width changes linearly from grip to gauge)
    for (s = [-1, 1])
        translate([s * reach - trans_len, 0, 0])
            linear_extrude(height = thickness)
                polygon([
                    [0, half_grip],
                    [trans_len, half_gauge + (half_grip - half_gauge) * (trans_len / trans_len)],
                    [trans_len + 1, half_gauge + (half_grip - half_gauge) * ((trans_len + 1) / trans_len)],
                    [-trans_len - 1, half_gauge + (half_grip - half_gauge) * ((-trans_len - 1) / trans_len)],
                    [-trans_len, half_gauge + (half_grip - half_gauge) * ((-trans_len) / trans_len)],
                    [0, -half_grip]
                ]);
