// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 3;     // specimen thickness (Z)
total_len   = 130;   // overall length along X
gauge_w     = 8;     // gauge section width (Y)
gauge_len   = 50;    // gauge section length (X)
grip_w      = 20;    // grip section width (Y)
grip_len    = 30;    // grip section length (X)
trans_len   = 10;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// grip ... trans ... gauge ... trans ... grip
// e.g. right grip ends at x = 65, gauge starts at x = 65

// ---------- Model ----------
difference() {
    // Outer block
    translate([-total_len / 2, -grip_w / 2, 0])
        cube([total_len, grip_w, thickness]);

    // Central gauge section
    translate([-half_gauge, -gauge_w / 2, -eps])
        cube([gauge_len, gauge_w, thickness + 2 * eps]);

    // Grip sections (cut from a slightly wider block to avoid coplanar faces)
    for (s = [-1, 1])
        translate([s * (half_gauge + trans_len) - half_grip,
                   -grip_w / 2 - s * 1,
                   -eps])
            cube([grip_len, grip_w + 2 * s * 1, thickness + 2 * eps]);

    // Transition sections: width changes linearly from grip_w to gauge_w
    for (s = [-1, 1]) {
        x0 = s * (half_gauge + trans_len);
        // rotate([90,0,0]) maps local Y to global X, so the
        // gradient runs along X over the next trans_len mm
        translate([x0 - trans_len, 0, -eps])
            rotate([90, 0, 0])
                linear_extrude(height = thickness + 2 * eps)
                    polygon([[-trans_len, -grip_w / 2 - s * 1],
                             [trans_len, -grip_w / 2 - s * 1],
                             [trans_len, gauge_w / 2],
                             [-trans_len, gauge_w / 2]]);
    }
}
