$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 10;    // length of each grip-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
// grip outer edge is transition_len away from gauge outer edge
x0 = half_gauge + transition_len;   // grip starts here (X)

// Width at the start of a transition (grip width), ends at gauge width
// Linear change: w(t) = w0 + (w1 - w0) * t / len
module transition(w0, w1, len) {
    translate([0, 0, thickness])
        linear_extrude(thickness)
            polygon(points = [
                [0, w0], [len, w1],
                [len + 0.01, w1], [0.01, w0]
            ]);
}

difference() {
    union() {
        // Central gauge section
        translate([-half_gauge, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Grip sections
        for (s = [-1, 1])
            translate([s * x0 - grip_length, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);

        // Transitions
        for (s = [-1, 1])
            translate([s * x0 - transition_len, 0, 0])
                transition(grip_width, gauge_width, transition_len);
    }
}
