// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 100;   // overall length along X
gauge_width    = 10;    // width of central gauge section (Y)
gauge_length   = 30;    // length of gauge section along X
grip_width     = 20;    // width of grip sections (Y)
grip_length    = 25;    // length of each grip section along X
transition_len  = 10;    // length of each grip-to-gauge transition
cut_extra      = 0.5;   // overshoot for clean boolean cuts

// Derived
grip_x0        = -total_length/2 + grip_length;  // grip start X
gauge_x0       = grip_x0 + grip_length;          // gauge start X
transition_x0  = gauge_x0 - transition_len;      // transition start X

// Width profile seen from above (y = f(x))
function width(x) =
    if (x < transition_x0)
        grip_width
    else if (x < gauge_x0)
        // linear drop from grip width to gauge width
        grip_width - (x - transition_x0) * (grip_width - gauge_width) / transition_len
    else if (x < gauge_x0 + gauge_length)
        gauge_width
    else
        // linear rise back to grip width
        gauge_width + (x - (gauge_x0 + gauge_length)) * (grip_width - gauge_width) / transition_len;

difference() {
    // Main plate
    linear_extrude(height = thickness)
        translate([-total_length/2, -100, 0])
            polygon(points = [for (i = [0 : 200]) [i * total_length/200, width(i * total_length/200)]]);

    // Central grip block (overlaps gauge and part of each transition)
    translate([-gauge_x0 - transition_len, -grip_width/2, -cut_extra])
        cube([gauge_x0 + transition_len - (-gauge_x0 - transition_len),
              grip_width,
              thickness + 2 * cut_extra]);
}
