            polygon([for (sx = [-1, 1]) [sx * total_length/2, 0]]);

    // Central grip block
    translate([-total_length/2 + grip_length, -grip_width/2, 0])
        cube([grip_length, grip_width, thickness]);

    // Far grip block
    translate([total_length/2 - grip_length, -grip_width/2, 0])
        cube([grip_length, grip_width, thickness]);

    // Gauge window, with rounded corners and overshoot
    translate([gauge_x0 - cut_extra, -gauge_width/2 - cut_extra, -cut_extra])
        cube([gauge_length + 2*cut_extra, gauge_width + 2*cut_extra, thickness + 2*cut_extra]);
}
