$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 140;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // length of each grip-to-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
half_grip  = grip_length / 2;
// grip end x = -total_length/2 + half_grip ; gauge end x = -half_gauge
// check: -70 + 17.5 = -52.5 ; -20 = -20  (overlap of 2.5 mm -> solid union)

// ---- Model ----
union() {
    // Left grip
    translate([-total_length / 2 + half_grip, -grip_width / 2, 0])
        cube([grip_length, grip_width, thickness]);

    // Right grip
    translate([total_length / 2 - half_grip, -grip_width / 2, 0])
        cube([grip_length, grip_width, thickness]);

    // Gauge section
    translate([-half_gauge, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);

    // Left transition (grip -> gauge)
    translate([-total_length / 2 + half_grip - transition_len,
               -grip_width / 2, 0])
        linear_extrude(thickness)
            polygon(points = [
                [0, grip_width / 2],
                [transition_len, gauge_width / 2],
                [transition_len, -gauge_width / 2],
                [0, -grip_width / 2]
            ]);

    // Right transition (gauge -> grip)
    translate([half_gauge - transition_len,
               -grip_width / 2, 0])
        linear_extrude(thickness)
            polygon(points = [
                [0, gauge_width / 2],
                [transition_len, grip_width / 2],
                [transition_len, -grip_width / 2],
                [0, -gauge_width / 2]
