// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 140;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // length of each grip-to-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
half_grip  = grip_length / 2;
// grip end x = -70, gauge end x = 70

module dogbone() {
    difference() {
        // Outer shape: grip -> transition -> gauge -> transition -> grip
        linear_extrude(height = thickness)
            polygon(points = [
                for (s = [-1, 1])
                    for (x = [-(half_grip + s * transition_len),
                               half_grip + s * transition_len])
                        [x, s * (grip_width + (transition_len - abs(x - (s > 0 ? half_gauge - transition_len : -half_gauge - transition_len))) * (gauge_width - grip_width) / transition_len)],
            ]);

        // Central relief: cut the gauge section down to 50% thickness
        translate([-(half_gauge + 1), -gauge_width / 2, thickness * 0.5])
            cube([gauge_length + 2, gauge_width, thickness * 0.5 + 1]);
    }
}

dogbone();
