// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to part thickness

// ---------- Parameters ----------
part_thickness   = 6;     // part thickness (Z)
outer_diameter   = 100;   // outer rim diameter
rim_width        = 6;     // rim width (radial)
hub_diameter     = 20;    // hub diameter
axle_hole_d      = 6;     // axle hole diameter
spoke_count      = 4;     // number of spokes
spoke_width      = 5;     // spoke width (radial and tangential)
spoke_start_ang  = 0;     // first spoke along +X axis
cut_extra        = 0.5;   // cutter overshoot past faces
$fn              = 128;   // curve resolution

// ---------- Derived ----------
outer_r = outer_diameter / 2;
hub_r   = hub_diameter / 2;
rim_r   = outer_r - rim_width;   // inner radius of rim ring

// ---------- Model ----------
union() {
    // Outer rim ring
    cylinder(d = outer_diameter, h = part_thickness, $fn = 256);
    translate([0, 0, -cut_extra])
        cylinder(d = 2 * rim_r, h = part_thickness + 2 * cut_extra, $fn = 256);

    // Hub with axle hole
    cylinder(d = hub_diameter, h = part_thickness, $fn = 128);
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_extra, $fn = 128);

    // Spokes from hub to rim
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start_ang + i * 360 / spoke_count;
        translate([hub_r, 0, 0])
            rotate([0, 0, a])
                translate([0, -spoke_width / 2, 0])
                    cube([outer_r - hub_r, spoke_width, part_thickness]);
    }
}
