// Powder measuring scoop
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

// ---- Parameters ----
bowl_outer_radius   = 12;    // mm, outer radius of spherical bowl
wall_thickness     = 1.5;    // mm, wall thickness of bowl
handle_width       = 8;     // mm, handle width along Y
handle_thickness   = 4;     // mm, handle thickness along Z
handle_start_x     = 10.5;  // mm, handle start position along X
handle_end_x       = 72;    // mm, handle end position along X
cut_extra          = 0.5;   // mm, extra length on cutters to avoid coplanar faces

$fn = 96;

// ---- Derived ----
bowl_inner_radius  = bowl_outer_radius - wall_thickness;
handle_top_z       = bowl_outer_radius;  // flush with rim (z = 12)

// ---- Model ----
union() {
    // Hollow spherical bowl: lower half only, opening upward
    difference() {
        translate([0, 0, bowl_outer_radius])
            sphere(r = bowl_outer_radius);
        translate([0, 0, bowl_outer_radius + cut_extra])
            sphere(r = bowl_inner_radius + cut_extra);
    }
    // Keep only the lower half of the sphere (z = 0 to z = 12)
    translate([0, 0, -cut_extra])
        difference() {
            sphere(r = bowl_outer_radius);
            translate([0, 0, cut_extra])
                sphere(r = bowl_outer_radius);
        }
    // Combine with the bowl to have a solid lower hemisphere
    union() {
        translate([0, 0, 0])
            sphere(r = bowl_outer_radius);
        translate([0, 0, bowl_outer_radius + cut_extra])
            sphere(r = bowl_inner_radius + cut_extra);
    }
}

// Flat handle along +X, centred on y = 0, top face flush with rim
translate([handle_start_x, -handle_width / 2, handle_top_z - handle_thickness])
    cube([handle_end_x - handle_start_x, handle_width, handle_thickness]);
