bowl_outer_r   = 12;    // outer radius of hemispherical bowl
bowl_wall      = 2;     // bowl wall thickness
bowl_inner_r   = bowl_outer_r - bowl_wall; // inner radius (10 mm)
bowl_center_z  = 12;    // sphere centre height (= rim height)

handle_x_start = 10;    // handle start along +X
handle_x_end   = 112;   // handle end along +X
handle_width   = 8;     // handle width (Y)
handle_thick   = 3;     // handle thickness (Z)
handle_top_z   = bowl_center_z;               // top flush with rim (z = 12)
handle_bot_z   = handle_top_z - handle_thick; // z = 9

eps = 0.5;              // overcut for clean boolean differences
$fn = 128;              // smoothness of curved surfaces

// ---------- Modules ----------
module bowl() {
    difference() {
        translate([0, 0, bowl_center_z]) sphere(r = bowl_outer_r);
        // hollow interior
        translate([0, 0, bowl_center_z]) sphere(r = bowl_inner_r);
        // remove upper half (everything above the rim)
        translate([-(bowl_outer_r + eps), -(bowl_outer_r + eps), bowl_center_z])
            cube([2 * (bowl_outer_r + eps), 2 * (bowl_outer_r + eps), bowl_outer_r + eps]);
    }
}

module handle() {
    translate([handle_x_start, -handle_width / 2, handle_bot_z])
        cube([handle_x_end - handle_x_start, handle_width, handle_thick]);
}

// ---------- Assembly ----------
difference() {
    union() {
        bowl();
        handle();
    }
    // keep bowl cavity clear of any handle material
    translate([0, 0, bowl_center_z]) sphere(r = bowl_inner_r);
}
