knuckle_off = (knuckle_n - 1) * knuckle_p / 2;   // 24 mm for 1st/3rd/5th

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders along X at y = 10, z = 3
        for (i = [-knuckle_off, -2, 2, knuckle_off])
            translate([i, 10, knuckle_z])
                cylinder(d = knuckle_d, h = plate_len + 2 * eps);
    }

    // Pin holes through every knuckle along the X axis
    for (i = [-knuckle_off, -2, 2, knuckle_off])
        translate([i, 10, knuckle_z])
            rotate([0, 90, 0])
                cylinder(d = knuckle_m, h = plate_len + 2 * eps);
