// ---- Star outline points ----
// Alternating outer/inner points, first outer point on +X axis
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (
            a = i * 180 / n_points,
            r = (i % 2 == 0) ? r_outer : r_inner
        )
        [r * cos(a), r * sin(a)]
];

// ---- Model ----
difference() {
    linear_extrude(height = thickness)
        polygon(points = star_pts);

