// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 100;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 10;    // transition section length (X)

// ---- Derived ----
grip_x0 = -(total_length / 2) + grip_length;  // grip start X
gauge_x0 = grip_x0 + grip_length;             // gauge start X

// ---- Model ----
union() {
    // Grip sections
    for (s = [-1, 1])
        translate([s * grip_x0, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

    // Gauge section
    translate([gauge_x0, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);

    // Transitions (linear width change from grip to gauge)
    for (s = [-1, 1]) {
        x0 = s > 0 ? gauge_x0 - transition_len : grip_x0;
        w0 = s > 0 ? gauge_width : grip_width;
        w1 = s > 0 ? grip_width : gauge_width;
        translate([x0, -w0 / 2, 0])
            linear_extrude(thickness)
                polygon([
                    [0, -w0 / 2],
                    [transition_len, -w1 / 2],
                    [transition_len, w1 / 2],
                    [0, w0 / 2]
                ]);
    }
}
