// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 100;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 10;    // transition section length (X)

// ---- Derived ----
grip_x0 = -(total_length / 2) + grip_length;  // grip start X
gauge_x0 = grip_x0 + grip_length;             // gauge start X

// Width at each end of a transition (linear change)
function trans_w(start_x, end_x) =
    (grip_width * (end_x - start_x) + gauge_width * (start_x - grip_x0)) /
    (end_x - grip_x0);

difference() {
    // Main body
    union() {
        // Grip sections
        for (s = [-1, 1])
            translate([s * grip_x0, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions
        for (s = [-1, 1])
            translate([s * gauge_x0 + gauge_length, -grip_width / 2, 0])
                linear_extrude(height = thickness)
                    polygon([
                        [0, -grip_width / 2],
                        [transition_len, -grip_width / 2],
                        [transition_len * 2, -gauge_width / 2],
                        [transition_len * 3, -gauge_width / 2],
                        [transition_len * 4, -grip_width / 2],
                        [transition_len * 5, -grip_width / 2],
                        [transition_len * 6, -grip_width / 2],
                        [transition_len * 7, -grip_width / 2],
                        [transition_len * 8, -grip_width / 2],
                        [transition_len * 9, -grip_width / 2],
                        [transition_len * 10, -grip_width / 2]
                    ]);
    }

    // Cut out the central gauge region, leaving a solid grip
    translate([gauge_x0 - 1, -gauge_width / 2 - 1, -1])
        cube([gauge_length + 2, gauge_width + 2, thickness + 2]);
}
