gauge_x0 = grip_x0 + grip_l;        // gauge start X
trans_x0 = gauge_x0 + transition_l; // transition start X (right side)

// Width at transition end (should equal grip width)
trans_w_end = grip_w + (grip_w - gauge_w) * transition_l / transition_l;

difference() {
    // Main body
    union() {
        // Left grip
        translate([-total_l / 2, -grip_w / 2, 0])
            cube([grip_l, grip_w, specimen_t]);
        // Right grip
        translate([grip_x0, -grip_w / 2, 0])
            cube([grip_l, grip_w, specimen_t]);
        // Gauge section
        translate([gauge_x0 - gauge_l, -gauge_w / 2, 0])
            cube([gauge_l, gauge_w, specimen_t]);
        // Transitions
        for (s = [-1, 1]) {
            translate([s * trans_x0 - transition_l, 0, 0])
                linear_extrude(specimen_t)
                    polygon([
                        [0, -trans_w_end / 2],
                        [transition_l, -trans_w_end / 2],
                        [transition_l, trans_w_end / 2],
                        [0, trans_w_end / 2]
                    ]);
        }
    }

    // Overlap removal (small overlap between sections)
    for (s = [-1, 1]) {
        translate([s * (grip_l - 0.01), -grip_w / 2 - 0.01, 0])
            cube([grip_l + 0.01, grip_w + 0.02, specimen_t + 0.01]);
