x0 = -total_len / 2 + half_grip + trans_len;   // gauge start X
x1 = x0 + gauge_len;                            // gauge end X

// ---------- Width profile (seen from above) ----------
function w(px) =
    if (px < -half_grip) grip_w;
    else if (px < -half_grip + trans_len)
        grip_w + (6 - grip_w) * (px - (-half_grip + trans_len)) / trans_len;
    else if (px < half_grip - trans_len) gauge_w;
    else if (px < half_grip)
        gauge_w + (grip_w - gauge_w) * (px - (half_grip - trans_len)) / trans_len;
    else grip_w;

