// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 10;    // length of each grip-to-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
// grip outer edge is at x = +/- (half_gauge + transition_len)
x0 = half_gauge + transition_len;   // grip start / gauge end X

module profile() {
    // Seen from above: central gauge, two grip blocks, two transitions
    union() {
        // Gauge section
        translate([-half_gauge, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Grip sections
        for (s = [-1, 1])
            translate([s * x0 - grip_length / 2, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip 20 -> gauge 6)
        for (t = [transition_len, -transition_len])
            for (s = [-1, 1])
                translate([s * (x0 + t), -grip_width / 2, 0])
                    linear_extrude(thickness)
                        polygon([
                            [0, -grip_width / 2],
                            [transition_len, -grip_width / 2],
                            [transition_len, grip_width / 2],
                            [0, grip_width / 2]
                        ]);
    }
}

difference() {
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([total_length, grip_width, thickness]);
    // Cut out the dog-bone profile, leaving the grip ends
    translate([-total_length / 2, -grip_width / 2, 0])
        difference() {
            cube([total_length, grip_width, thickness]);
            translate([-x0, -grip_width / 2, 0])
                cube([x0 + grip_length / 2, grip_width, thickness]);
            translate([x0 - grip_length / 2, -grip_width / 2, 0])
                cube([grip_length / 2 + x0, grip_width, thickness]);
        }
}
